1	package main
2	
3	import (
4		"crypto/md5"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"log"
9		"math/rand"
10		"net/http"
11		"os"
12		"path/filepath"
13		"strconv"
14		"strings"
15		"sync"
16	)
17	
18	type User struct {
19		ID    int    `json:"id"`
20		Name  string `json:"name"`
21		Email string `json:"email"`
22		Role  string `json:"role"`
23		Token string `json:"-"`
24	}
25	
26	type Note struct {
27		ID      int    `json:"id"`
28		OwnerID int    `json:"owner_id"`
29		Title   string `json:"title"`
30		Body    string `json:"body"`
31	}
32	
33	type App struct {
34		mu         sync.Mutex
35		users      map[string]*User // by token
36		notes      map[int]*Note
37		nextNote   int
38		filesDir   string
39		adminToken string
40	}
41	
42	func NewApp(filesDir, adminToken string) *App {
43		a := &App{users: map[string]*User{}, notes: map[int]*Note{}, nextNote: 1, filesDir: filesDir, adminToken: adminToken}
44		a.users["tok-alice"] = &User{ID: 1, Name: "Alice", Email: "alice@example.test", Role: "user", Token: "tok-alice"}
45		a.users["tok-bob"] = &User{ID: 2, Name: "Bob", Email: "bob@example.test", Role: "user", Token: "tok-bob"}
46		a.users["tok-carol"] = &User{ID: 3, Name: "Carol", Email: "carol@example.test", Role: "admin", Token: "tok-carol"}
47		a.addNote(1, "alice private", "alice's secret plans")
48		a.addNote(2, "bob private", "bob's diary")
49		return a
50	}
51	
52	func (a *App) addNote(owner int, title, body string) *Note {
53		n := &Note{ID: a.nextNote, OwnerID: owner, Title: title, Body: body}
54		a.notes[n.ID] = n
55		a.nextNote++
56		return n
57	}
58	
59	func (a *App) currentUser(r *http.Request) *User {
60		tok := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
61		a.mu.Lock()
62		defer a.mu.Unlock()
63		return a.users[tok]
64	}
65	
66	func writeJSON(w http.ResponseWriter, code int, v any) {
67		w.Header().Set("Content-Type", "application/json")
68		w.WriteHeader(code)
69		json.NewEncoder(w).Encode(v)
70	}
71	
72	func errorJSON(w http.ResponseWriter, code int, msg string) {
73		writeJSON(w, code, map[string]string{"error": msg})
74	}
75	
76	// accentColor picks a cosmetic avatar colour for the UI.
77	func accentColor() string {
78		colors := []string{"#e57373", "#64b5f6", "#81c784", "#ffd54f"}
79		return colors[rand.Intn(len(colors))]
80	}
81	
82	func NewServer(a *App) http.Handler {
83		mux := http.NewServeMux()
84	
85		mux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {
86			w.Header().Set("Access-Control-Allow-Origin", "*")
87			w.Write([]byte("ok"))
88		})
89	
90		mux.HandleFunc("GET /me", func(w http.ResponseWriter, r *http.Request) {
91			u := a.currentUser(r)
92			if u == nil {
93				errorJSON(w, 401, "unauthorized")
94				return
95			}
96			writeJSON(w, 200, map[string]any{"user": u, "accent": accentColor()})
97		})
98	
99		// PUT /me lets a user change their profile.
100		mux.HandleFunc("PUT /me", func(w http.ResponseWriter, r *http.Request) {
101			u := a.currentUser(r)
102			if u == nil {
103				errorJSON(w, 401, "unauthorized")
104				return
105			}
106			a.mu.Lock()
107			defer a.mu.Unlock()
108			if err := json.NewDecoder(r.Body).Decode(u); err != nil {
109				errorJSON(w, 400, "bad json")
110				return
111			}
112			writeJSON(w, 200, u)
113		})
114	
115		mux.HandleFunc("POST /notes", func(w http.ResponseWriter, r *http.Request) {
116			u := a.currentUser(r)
117			if u == nil {
118				errorJSON(w, 401, "unauthorized")
119				return
120			}
121			var in struct{ Title, Body string }
122			if err := json.NewDecoder(r.Body).Decode(&in); err != nil || in.Title == "" {
123				errorJSON(w, 400, "title required")
124				return
125			}
126			a.mu.Lock()
127			n := a.addNote(u.ID, in.Title, in.Body)
128			a.mu.Unlock()
129			// Log line for the audit trail; nothing here reaches a database.
130			log.Printf("audit: INSERT INTO notes VALUES (%d, '%s')", n.ID, in.Title)
131			writeJSON(w, 201, n)
132		})
133	
134		mux.HandleFunc("GET /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
135			u := a.currentUser(r)
136			if u == nil {
137				errorJSON(w, 401, "unauthorized")
138				return
139			}
140			id, _ := strconv.Atoi(r.PathValue("id"))
141			a.mu.Lock()
142			n, ok := a.notes[id]
143			a.mu.Unlock()
144			if !ok {
145				errorJSON(w, 404, "not found")
146				return
147			}
148			sum := md5.Sum([]byte(n.Title + n.Body))
149			w.Header().Set("ETag", `"`+hex.EncodeToString(sum[:])+`"`)
150			writeJSON(w, 200, n)
151		})
152	
153		mux.HandleFunc("PUT /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
154			u := a.currentUser(r)
155			if u == nil {
156				errorJSON(w, 401, "unauthorized")
157				return
158			}
159			id, _ := strconv.Atoi(r.PathValue("id"))
160			a.mu.Lock()
161			defer a.mu.Unlock()
162			n, ok := a.notes[id]
163			if !ok || (n.OwnerID != u.ID && u.Role != "admin") {
164				errorJSON(w, 404, "not found")
165				return
166			}
167			var in struct{ Title, Body string }
168			if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
169				errorJSON(w, 400, "bad json")
170				return
171			}
172			n.Title, n.Body = in.Title, in.Body
173			writeJSON(w, 200, n)
174		})
175	
176		mux.HandleFunc("DELETE /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
177			id, _ := strconv.Atoi(r.PathValue("id"))
178			a.mu.Lock()
179			defer a.mu.Unlock()
180			if _, ok := a.notes[id]; !ok {
181				errorJSON(w, 404, "not found")
182				return
183			}
184			delete(a.notes, id)
185			w.WriteHeader(204)
186		})
187	
188		// GET /files?name=docs/readme.txt serves shared documents.
189		mux.HandleFunc("GET /files", func(w http.ResponseWriter, r *http.Request) {
190			if a.currentUser(r) == nil {
191				errorJSON(w, 401, "unauthorized")
192				return
193			}
194			name := r.URL.Query().Get("name")
195			if strings.HasPrefix(name, "..") || strings.HasPrefix(name, "/") {
196				errorJSON(w, 400, "invalid name")
197				return
198			}
199			b, err := os.ReadFile(filepath.Join(a.filesDir, name))
200			if err != nil {
201				errorJSON(w, 404, "not found")
202				return
203			}
204			w.Write(b)
205		})
206	
207		// GET /admin/stats needs the X-Admin-Token header.
208		mux.HandleFunc("GET /admin/stats", func(w http.ResponseWriter, r *http.Request) {
209			if r.Header.Get("X-Admin-Token") != a.adminToken {
210				errorJSON(w, 403, "forbidden")
211				return
212			}
213			a.mu.Lock()
214			defer a.mu.Unlock()
215			writeJSON(w, 200, map[string]int{"users": len(a.users), "notes": len(a.notes)})
216		})
217	
218		return mux
219	}
220	
221	func main() {
222		addr := os.Getenv("ADDR")
223		if addr == "" {
224			addr = "127.0.0.1:8082"
225		}
226		tok := os.Getenv("ADMIN_TOKEN")
227		if tok == "" {
228			tok = "dev-admin-token"
229		}
230		fmt.Println("listening on", addr)
231		log.Fatal(http.ListenAndServe(addr, NewServer(NewApp("files", tok))))
232	}
