139				errorJSON(w, 401, "unauthorized")
140				return
141			}
142			id, _ := strconv.Atoi(r.PathValue("id"))
143			a.mu.Lock()
144			n, ok := a.notes[id]
145			a.mu.Unlock()
146			if !ok || (n.OwnerID != u.ID && u.Role != "admin") {
147				errorJSON(w, 404, "not found")
148				return
149			}
150			sum := md5.Sum([]byte(n.Title + n.Body))
151			w.Header().Set("ETag", `"`+hex.EncodeToString(sum[:])+`"`)
152			writeJSON(w, 200, n)
153		})
